//! display/dc/dce/dce_i2c_hw.{h,c} (Linux 6.18.55), with the `i2c_hw_regs`/
//! `i2c_shifts`/`i2c_masks` table of dcn21_resource.c: the hardware I2C engines
//! of Renoir's ddc loop. Renoir has `res_cap_rn.num_ddc` (5) of them, on DDC
//! banks 1..5.
//!
//! `dcn21_i2c_hw_create` runs the full dcn2→dcn1→dce112→dce100→dce construct
//! chain (each layer overriding one field); it writes no register. The register
//! table is machine-generated by `dcgen.py` from `I2C_HW_ENGINE_COMMON_REG_LIST`
//! / `I2C_COMMON_MASK_SH_LIST_DCN2` (DDC banks 1..5).
#![allow(dead_code)]

use crate::dc_types::dc_bios;
use crate::regs::*;
use alloc::boxed::Box;

/// The I2C timing/buffer constants (dce_i2c_hw.h enum).
const I2C_SETUP_TIME_LIMIT_DCE: u32 = 255;
const I2C_SETUP_TIME_LIMIT_DCN: u32 = 3;
const I2C_HW_BUFFER_SIZE_DCE100: u32 = 538;
const I2C_HW_BUFFER_SIZE_DCE: u32 = 144;
const I2C_SEND_RESET_LENGTH_9: u32 = 9;
const DEFAULT_I2C_HW_SPEED: u32 = 50;
const DEFAULT_I2C_HW_SPEED_100KHZ: u32 = 100;

/// `struct dce_i2c_hw` (dce_i2c_hw.h): a hardware I2C engine. Ported
/// grow-as-reached — `ddc` (the attached DDC line) is None until the ddc
/// service lands, and `ctx` is not stored (see `clock_source`).
#[derive(Default)]
pub struct dce_i2c_hw {
    pub engine_keep_power_up_count: u32,
    pub transaction_count: u32,
    pub buffer_used_bytes: u32,
    pub buffer_used_write: u32,
    pub reference_frequency: u32,
    pub default_speed: u32,
    pub engine_id: u32,
    pub setup_limit: u32,
    pub send_reset_length: u32,
    pub buffer_size: u32,
    pub regs: Option<&'static dce_i2c_registers>,
    pub shifts: Option<&'static dce_i2c_shift>,
    pub masks: Option<&'static dce_i2c_mask>,
}

/// `dce_i2c_hw_construct` (dce_i2c_hw.c): the base layer. `reference_frequency`
/// is the VBIOS crystal frequency halved (0 until bios_parser2 populates it).
pub fn dce_i2c_hw_construct(
    h: &mut dce_i2c_hw,
    bios: &dc_bios,
    engine_id: u32,
    regs: &'static dce_i2c_registers,
    shifts: &'static dce_i2c_shift,
    masks: &'static dce_i2c_mask,
) {
    h.engine_id = engine_id;
    h.reference_frequency = bios.fw_info.pll_info.crystal_frequency >> 1;
    h.regs = Some(regs);
    h.shifts = Some(shifts);
    h.masks = Some(masks);
    h.buffer_used_bytes = 0;
    h.transaction_count = 0;
    h.engine_keep_power_up_count = 1;
    h.default_speed = DEFAULT_I2C_HW_SPEED;
    h.send_reset_length = 0;
    h.setup_limit = I2C_SETUP_TIME_LIMIT_DCE;
    h.buffer_size = I2C_HW_BUFFER_SIZE_DCE;
}

/// `dce100_i2c_hw_construct` (dce_i2c_hw.c).
pub fn dce100_i2c_hw_construct(
    h: &mut dce_i2c_hw,
    bios: &dc_bios,
    engine_id: u32,
    regs: &'static dce_i2c_registers,
    shifts: &'static dce_i2c_shift,
    masks: &'static dce_i2c_mask,
) {
    dce_i2c_hw_construct(h, bios, engine_id, regs, shifts, masks);
    h.buffer_size = I2C_HW_BUFFER_SIZE_DCE100;
}

/// `dce112_i2c_hw_construct` (dce_i2c_hw.c).
pub fn dce112_i2c_hw_construct(
    h: &mut dce_i2c_hw,
    bios: &dc_bios,
    engine_id: u32,
    regs: &'static dce_i2c_registers,
    shifts: &'static dce_i2c_shift,
    masks: &'static dce_i2c_mask,
) {
    dce100_i2c_hw_construct(h, bios, engine_id, regs, shifts, masks);
    h.default_speed = DEFAULT_I2C_HW_SPEED_100KHZ;
}

/// `dcn1_i2c_hw_construct` (dce_i2c_hw.c).
pub fn dcn1_i2c_hw_construct(
    h: &mut dce_i2c_hw,
    bios: &dc_bios,
    engine_id: u32,
    regs: &'static dce_i2c_registers,
    shifts: &'static dce_i2c_shift,
    masks: &'static dce_i2c_mask,
) {
    dce112_i2c_hw_construct(h, bios, engine_id, regs, shifts, masks);
    h.setup_limit = I2C_SETUP_TIME_LIMIT_DCN;
}

/// `dcn2_i2c_hw_construct` (dce_i2c_hw.c). The `scl_reset_length10` debug
/// override defaults off, so the reset length is the 9-cycle value.
pub fn dcn2_i2c_hw_construct(
    h: &mut dce_i2c_hw,
    bios: &dc_bios,
    engine_id: u32,
    regs: &'static dce_i2c_registers,
    shifts: &'static dce_i2c_shift,
    masks: &'static dce_i2c_mask,
) {
    dcn1_i2c_hw_construct(h, bios, engine_id, regs, shifts, masks);
    h.send_reset_length = I2C_SEND_RESET_LENGTH_9;
}

/// `dcn21_i2c_hw_create` (dcn21_resource.c): allocate and construct the engine
/// for ddc index `inst` (0-based into `I2C_REGS`, DDC banks 1..5).
pub fn dcn21_i2c_hw_create(bios: &dc_bios, inst: u32) -> Box<dce_i2c_hw> {
    let mut h = Box::new(dce_i2c_hw::default());
    dcn2_i2c_hw_construct(&mut h, bios, inst, &I2C_REGS[inst as usize], &I2C_SHIFT, &I2C_MASK);
    h
}

